-- Níveis de calor dos dias de demonstração (FONTE = DEMONSTRACAO, não é dado do INMET)
MERGE INTO TMC_NIVEL_CALOR t USING (SELECT DATE '2026-11-23' DATA_LOCAL, 2 NIVEL, 'Atencao' NOME_NIVEL, 35.4 IC_MAX_C, 'PREVISTO' ORIGEM, 'DEMONSTRACAO' FONTE, 'A707-2003-2026-v1' VERSAO_LIMIAR FROM DUAL) s ON (t.DATA_LOCAL = s.DATA_LOCAL AND t.ORIGEM = s.ORIGEM AND t.FONTE = s.FONTE AND t.VERSAO_LIMIAR = s.VERSAO_LIMIAR) WHEN NOT MATCHED THEN INSERT (DATA_LOCAL, NIVEL, NOME_NIVEL, IC_MAX_C, ORIGEM, FONTE, VERSAO_LIMIAR) VALUES (s.DATA_LOCAL, s.NIVEL, s.NOME_NIVEL, s.IC_MAX_C, s.ORIGEM, s.FONTE, s.VERSAO_LIMIAR);
MERGE INTO TMC_NIVEL_CALOR t USING (SELECT DATE '2026-11-24' DATA_LOCAL, 4 NIVEL, 'Alto risco' NOME_NIVEL, 37.2 IC_MAX_C, 'PREVISTO' ORIGEM, 'DEMONSTRACAO' FONTE, 'A707-2003-2026-v1' VERSAO_LIMIAR FROM DUAL) s ON (t.DATA_LOCAL = s.DATA_LOCAL AND t.ORIGEM = s.ORIGEM AND t.FONTE = s.FONTE AND t.VERSAO_LIMIAR = s.VERSAO_LIMIAR) WHEN NOT MATCHED THEN INSERT (DATA_LOCAL, NIVEL, NOME_NIVEL, IC_MAX_C, ORIGEM, FONTE, VERSAO_LIMIAR) VALUES (s.DATA_LOCAL, s.NIVEL, s.NOME_NIVEL, s.IC_MAX_C, s.ORIGEM, s.FONTE, s.VERSAO_LIMIAR);

